"""Classical min-cut Phi: nonnegativity, the reducibility dichotomy,
scaling, monotonicity and symmetrization on a 3-node causal system."""
from typing import List, Tuple


def nontrivial_bipartitions(n: int) -> List[Tuple[int, ...]]:
    out = []
    for bits in range(1, (1 << n) - 1):
        s = tuple(i for i in range(n) if (bits >> i) & 1)
        if 0 < len(s) < n:
            out.append(s)
    return out


def cross_info(w: List[List[float]], s: Tuple[int, ...]) -> float:
    comp = [j for j in range(len(w)) if j not in set(s)]
    return sum(w[i][j] for i in s for j in comp)


def phi(w: List[List[float]]) -> float:
    return min(cross_info(w, s) for s in nontrivial_bipartitions(len(w)))


connected = [[0, 1, 2], [1.5, 0, 0.5], [0.8, 1.2, 0]]
disconnected = [[0, 0, 0], [0, 0, 3], [0, 4, 0]]
print("Phi(connected)    =", phi(connected), "(strongly positive => > 0)")
print("Phi(disconnected) =", phi(disconnected), "(free cut => 0)")
print("scaling:  Phi(2.5*C) =", phi([[2.5 * x for x in r] for r in connected]),
      "= 2.5 * Phi(C) =", 2.5 * phi(connected))

"""Multipartite MIP: one product cut forces Phi=0; the discrete area-law
bound rank <= d^|complement| on a 3-site, local-dimension-2 state."""
from itertools import product
import numpy as np


def cut_rank(psi, n, d, s):
    s_set = set(s)
    in_s = [i for i in range(n) if i in s_set]
    out_s = [i for i in range(n) if i not in s_set]
    rows = list(product(range(d), repeat=len(in_s)))
    cols = list(product(range(d), repeat=len(out_s)))
    M = np.zeros((len(rows), len(cols)), dtype=complex)
    for ri, rc in enumerate(rows):
        for ci, cc in enumerate(cols):
            x = [0] * n
            for k, i in enumerate(in_s):
                x[i] = rc[k]
            for k, i in enumerate(out_s):
                x[i] = cc[k]
            M[ri, ci] = psi(tuple(x))
    return int(np.linalg.matrix_rank(M))


n, d = 3, 2
f = {0: 1.0 + 0j, 1: 2.0 + 0j}
g = {(0, 0): 1.0, (0, 1): -1.0, (1, 0): 0.5, (1, 1): 2.0}
psi = lambda x: f[x[0]] * g[(x[1], x[2])]   # factors across cut {0}
print("rank at cut (0,) =", cut_rank(psi, n, d, (0,)), "=> product cut => Phi_MIP = 0")

rng = np.random.default_rng(1)
tab = {x: complex(rng.standard_normal(), rng.standard_normal())
       for x in product(range(d), repeat=n)}
gen = lambda x: tab[x]
for k in range(1, n):
    s = tuple(range(k))
    print(f"cut {s}: rank =", cut_rank(gen, n, d, s), "<= d^|comp| =", d ** (n - len(s)))

